import{_ as r,o,c as n,a2 as s}from"./chunks/framework.CYjxsSA2.js";const c=JSON.parse('{"title":"漏洞管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vulnreports.md","filePath":"guide/vulnreports.md"}'),a={name:"guide/vulnreports.md"};function d(e,t,l,i,g,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="漏洞管理" tabindex="-1">漏洞管理 <a class="header-anchor" href="#漏洞管理" aria-label="Permalink to &quot;漏洞管理&quot;">​</a></h1><p>项目内的<strong>漏洞管理</strong>页是成果交付中心，两个页签：</p><table tabindex="0"><thead><tr><th>页签</th><th>内容</th></tr></thead><tbody><tr><td><strong>发现</strong></td><td>直读漏洞账本、跨任务汇总，按严重度分诊</td></tr><tr><td><strong>侦察报告</strong></td><td>按资产（站点 / IP）归集的侦察报告，可导出</td></tr></tbody></table><h2 id="发现-风险分诊流" tabindex="-1">发现：风险分诊流 <a class="header-anchor" href="#发现-风险分诊流" aria-label="Permalink to &quot;发现：风险分诊流&quot;">​</a></h2><p>版面按<strong>严重度</strong>搭骨架，自上而下：</p><ul><li><strong>工具条</strong> —— 搜索、档位切换（全部 / 严重 / 高 / 中 / 低 / 信息）、筛选（状态 / 类型 / 来源任务）、视图（分组维度与排序）</li><li><strong>风险带</strong> —— 一行看完整体态势：发现总数、待处理数、各档位占比</li><li><strong>资产 chips</strong> —— 点一下只看某台机器的问题</li><li><strong>档位泳道</strong> —— 每个严重度一条泳道，段头写着档位、条数、行动指引；泳道内是发现卡片</li><li><strong>卡片</strong> —— 标题点开即内联展开证据（请求 / 响应 / 复现步骤）；元信息含漏洞类型、资产、状态、来源任务（可点击跳到产生它的会话）</li></ul><div class="tip custom-block"><p class="custom-block-title">默认「按档位」分组</p><p>切到「按资产」看同一台机器上的全部问题，切到「按任务」核对某次会话的战果，「不分组」则按当前排序平铺。</p></div><h2 id="漏洞确认口径" tabindex="-1">漏洞确认口径 <a class="header-anchor" href="#漏洞确认口径" aria-label="Permalink to &quot;漏洞确认口径&quot;">​</a></h2><p>「发现了疑似漏洞」与「确认了漏洞」是两件事，平台用<strong>账本状态</strong>分开：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><strong>待确认</strong></td><td>已登记疑点，尚未验证</td></tr><tr><td><strong>测试中</strong></td><td>正在验证</td></tr><tr><td><strong>已确认</strong></td><td>验证通过，且有取证支撑</td></tr><tr><td><strong>已否定</strong></td><td>验证后判定不成立</td></tr><tr><td><strong>死路</strong></td><td>已验证为不可利用，记录以免重复尝试</td></tr></tbody></table><p>几条固定规则：</p><ul><li><strong>只有「已确认」才算已确认漏洞</strong>，其余按原状态标注</li><li><strong>确认需要取证支撑</strong>，没有原始请求 / 响应的条目不能升级为已确认</li><li><strong>严重度只升不降</strong>，重复登记时不会被后来的低自评覆盖</li><li><strong>本次运行与历史运行严格区分</strong>，不把几天前的截图当作本次成果</li></ul><p>发现条目会给出证据来源提示：</p><table tabindex="0"><thead><tr><th>提示</th><th>含义</th></tr></thead><tbody><tr><td><strong>本条没有请求报文（仅为文本登记）</strong></td><td>来自文本描述，尚未取得流量取证</td></tr><tr><td><strong>本次运行未取得证据（证据来自历史运行）</strong></td><td>证据取自同项目更早的运行，不算本次战果</td></tr></tbody></table><h2 id="侦察报告" tabindex="-1">侦察报告 <a class="header-anchor" href="#侦察报告" aria-label="Permalink to &quot;侦察报告&quot;">​</a></h2><p>报告按<strong>资产</strong>归集，一行一个资产：</p><ul><li>搜索资产名或报告名</li><li><strong>单个导出</strong>或<strong>批量导出</strong>：Markdown（无图片）/ PDF（可复制文本）</li><li>可删除某资产的全部报告</li><li>侦察仍在进行时提示「完成后可查看报告」</li><li>报告与军团会话一一对应，可直接跳回产生它的那次会话</li></ul>',17)])])}const u=r(a,[["render",d]]);export{c as __pageData,u as default};
